class RadiantHeater(Equipment):
    """
    A piece of `Equipment` with heating or cooling surface that delivers 50% or more of its heat transfer by radiation.
    A `RadiantHeater` shall:
    
    - Have the role `Role-Heating`.
    
    - Have at least one outlet connection point using the medium `Light-Infrared`.
    
    - Conform to exactly one of the following patterns:
      - **Pattern 1:**
        - Exactly one inlet connection point using the medium `Constituent-Electricity` or `Fluid-NaturalGas`.
      - **Pattern 2:**
        - Exactly one inlet connection point using the medium `Fluid-Water`.
        - Exactly one outlet connection point using the medium `Fluid-Water`.
    
    
    Ontology: WATR — http://data.ashrae.org/standard223#RadiantHeater
    """

    _classinfo = _ClassInfo(
        iri='http://data.ashrae.org/standard223#RadiantHeater',
        ontology=ONTOLOGY,
        registry=_REGISTRY,
        label='Radiant heater',
        definition='\nA piece of `Equipment` with heating or cooling surface that delivers 50% or more of its heat transfer by radiation.\nA `RadiantHeater` shall:\n\n- Have the role `Role-Heating`.\n\n- Have at least one outlet connection point using the medium `Light-Infrared`.\n\n- Conform to exactly one of the following patterns:\n  - **Pattern 1:**\n    - Exactly one inlet connection point using the medium `Constituent-Electricity` or `Fluid-NaturalGas`.\n  - **Pattern 2:**\n    - Exactly one inlet connection point using the medium `Fluid-Water`.\n    - Exactly one outlet connection point using the medium `Fluid-Water`.\n',
        cp_slots=(
            _CPSlot(cp_class='OutletConnectionPoint', direction='out', medium='http://data.ashrae.org/standard223#Light-Infrared', medium_options=(), min_count=1, max_count=None),
        ),
        cp_constraints=(
            _CPConstraint(operator='xone', children=(
                _CPConstraint(operator='slot', slot=_CPSlot(cp_class='InletConnectionPoint', direction='in', medium=None, medium_options=('http://data.ashrae.org/standard223#Constituent-Electricity', 'http://data.ashrae.org/standard223#Fluid-NaturalGas'), min_count=1, max_count=None)),
                _CPConstraint(operator='and', children=(
                    _CPConstraint(operator='slot', slot=_CPSlot(cp_class='OutletConnectionPoint', direction='out', medium='http://data.ashrae.org/standard223#Fluid-Water', medium_options=(), min_count=1, max_count=None)),
                    _CPConstraint(operator='slot', slot=_CPSlot(cp_class='InletConnectionPoint', direction='in', medium='http://data.ashrae.org/standard223#Fluid-Water', medium_options=(), min_count=1, max_count=None)),
                )),
            )),
        ),
    )

